+                    transformId,
+                    JUNIOR_USERNAME,
+                    sourceIndexName,
+                    destIndexName
+                )
+            )
+        );
+
+        putTransform(
+            transformId,
+            Strings.toString(config),
+            RequestOptions.DEFAULT.toBuilder()
+                .addHeader(AUTH_KEY, SENIOR_HEADER)
+                .addParameter("defer_validation", String.valueOf(false))
+                .build()
+        );
+    }
